  const a = lines[i], b = lines[i + 1];
  if (a.startsWith("Expected: ") && b.startsWith("Received: ")) pairs.push([a.slice(10), b.slice(10)]);
  else if (a.startsWith("- ") && b.startsWith("+ ") && a !== "- Expected" && b !== "+ Received")
