    const { t, sleeps } = rig(ff.fetch);
    const got = await sendGeneration(glm({ maxRetries: 1 }), [rq("a.v1")], t);
    expect(`${ff.calls.length} ${JSON.stringify(sleeps)} ${got.answers[0]?.error}`, `status ${s} is retried`).toBe(
