    });
  } finally {
    t.rm();
  }
});

test("§2.2: stale inputs keep previousDiff null", async () => {
  const { t, deps } = harness();
  try {
    t.write("shared.ts", "export const s = 0;\n");
    t.write("answers/a.v1.md", fenced("MARK_A"));
    t.write("answers/b.v1.md", fenced("MARK_B"));
