  type, model: type === "stub" ? "stub" : "z-ai/glm-5.3", apiKey: type === "stub" ? null : "k", baseUrl: "https://openrouter.ai/api/v1",
  route: "sync", concurrency: 1, providerOrder: null, reasoning: null, timeoutMs: 600000, maxRetries: 0, answersDir });
