test("§2.2: dirty paths are sorted, not in git's order (tracked changes before untracked)", () => {
  const r = tmpRepo();
  try {
    r.write("z.md", "one\n");
    r.git(["add", "z.md"]);
    r.git(["commit", "-q", "-m", "z"]);
    r.write("z.md", "two\n");
    r.write("a.txt", "x\n");
    expect(r.git(["status", "--porcelain", "--untracked-files=all"]), "git's order").toBe("M z.md\n?? a.txt");
