test("§2.2: steps — uses and data objects distinct in step order, other targets ignored", () => {
  const f = { name: "F", description: "F.", behavior: "B.", requirements: [], guardrails: [], preconditions: [],
    examples: [{ given: "g", when: "w", then: "t", ref: null }],
